function validate([amount]) {
  if (!Array.isArray(amount) || amount.length !== 3) return 'amount must hold exactly 3 values.';
  if (amount.some(v => !Number.isInteger(v) || v < 0 || v > 100)) return 'Each amount is a whole number from 0 to 100.';
  return null;
}

