function fillCups(amount) {
  const cups = [...amount];
  cups.sort((a, b) => b - a);
  let seconds = 0;

  while (cups[0] > 0) {
    cups[0]--;
    if (cups[1] > 0) {
      cups[1]--;
    }
    seconds++;
    cups.sort((a, b) => b - a);
  }
  return seconds;
}

