function fillCups(amount) {
  // A schedule is fixed by how many double seconds use each pair of kinds; the order does not matter.
  // Try every count of (cold, warm) and (cold, hot) seconds, then use as many (warm, hot) seconds as fit.
  const [cold, warm, hot] = amount;
  let best = Infinity;
  for (let x = 0; x <= Math.min(cold, warm); x++) {
    for (let y = 0; x + y <= cold && y <= hot; y++) {
      const z = Math.min(warm - x, hot - y);
      best = Math.min(best, cold + warm + hot - (x + y + z));
    }
  }
  return best;
}

