function generate(rand, size) {
  const top = size === 'large' ? 100 : 6;
  const pick = () => Math.floor(rand() * (top + 1));
  const shape = rand();
  const amount = [pick(), pick(), pick()];
  const spot = Math.floor(rand() * 3);
  if (shape < 0.15) {
    // One kind dominates the other two.
    for (let i = 0; i < 3; i++) if (i !== spot) amount[i] = Math.floor(rand() * 3);
  } else if (shape < 0.25) {
    amount[spot] = 0;
  }
  return [amount];
}
